-- Bible in a year 2023 (Oct 12 – Dec 30, 73 days) from the Google Doc. Run once, after bible.sql.
-- Re-running is safe: a day that's already there gets replaced.
on conflict (entry_date) do update set
  ot_passage = excluded.ot_passage, ot_notes = excluded.ot_notes,
  nt_passage = excluded.nt_passage, nt_notes = excluded.nt_notes, updated_at = now();
